-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

CREATE OR REPLACE FUNCTION public.search_word_corrections(p_query text)
 RETURNS TABLE(word text, correction text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
  select q.word, c.word
  from (select distinct t as word
        from regexp_split_to_table(lower(left(coalesce(p_query, ''), 200)), '\s+') t
        where t ~ '^[[:alpha:]]{4,30}$'
        limit 8) q
  cross join lateral (
    select s.word from public.search_words s
    order by s.word <-> q.word, s.uses desc
    limit 1) c
  where not exists (select 1 from public.search_words s where s.word = q.word)
    and similarity(c.word, q.word) >= 0.35;
$function$;

grant execute on function public.search_word_corrections(p_query text) to anon;
grant execute on function public.search_word_corrections(p_query text) to authenticated;
grant execute on function public.search_word_corrections(p_query text) to service_role;
